// biome-ignore-all lint/suspicious/noTemplateCurlyInString: these strings are bash, Compose and GitHub Actions syntax, not JavaScript templates.
import type { DeployPlan } from "@opscrew/plan-schema";
import { stringify } from "yaml";
import { TUNNEL_ORIGIN_PORT, tunnelMode } from "../tunnel";
import type { RenderContext, RenderedFile } from "../types";

export const POSTGRES_IMAGE = "postgres:17-alpine";
export const VALKEY_IMAGE = "valkey/valkey:8-alpine";
export const CADDY_IMAGE = "caddy:2-alpine";

const HEADER = [
  "# Generated by OpsCrew from opscrew/plan.yaml; `opscrew provision` regenerates it.",
  "# The deploy workflow copies it to /srv/app on the server.",
].join("\n");

/** Hostnames Caddy serves; empty when the plan has no domain yet. */
export function siteHosts(plan: DeployPlan): string[] {
  const domain = plan.dns.domain;
  if (!domain) return [];
  return plan.dns.www ? [domain, `www.${domain}`] : [domain];
}

/** `opscrew/runtime/compose.yaml`: app, optional Postgres and Valkey, and Caddy in front. */
export function renderCompose(plan: DeployPlan, _ctx: RenderContext): RenderedFile {
  const hardening = { security_opt: ["no-new-privileges:true"] };
  const app: Record<string, unknown> = {
    image: "${APP_IMAGE:?APP_IMAGE is not set; deploy with the OpsCrew workflow}",
    restart: "unless-stopped",
    env_file: ["app.env"],
    environment: { PORT: String(plan.app.port) },
    ...hardening,
    cap_drop: ["ALL"],
    networks: ["internal"],
  };
  const dependsOn: Record<string, { condition: string }> = {};
  const services: Record<string, unknown> = { app };
  const release = plan.app.releaseCommand;
  if (release !== undefined) {
    // A one-off container of the app's image, environment and network; only
    // `docker compose run release` starts it (the deploy does, before the app is replaced).
    services.release = {
      image: app.image,
      profiles: ["release"],
      env_file: ["app.env"],
      environment: { PORT: String(plan.app.port) },
      // `$$` keeps Compose from substituting variables: the shell in the container sees `$`.
      command: ["sh", "-c", release.replaceAll("$", () => "$$")],
      ...hardening,
      cap_drop: ["ALL"],
      networks: ["internal"],
    };
  }

  if (plan.services.postgres) {
    services.db = {
      image: POSTGRES_IMAGE,
      restart: "unless-stopped",
      env_file: ["db.env"],
      volumes: ["/srv/data/postgres:/var/lib/postgresql/data"],
      healthcheck: {
        test: ["CMD-SHELL", "pg_isready -U $${POSTGRES_USER} -d $${POSTGRES_DB}"],
        interval: "10s",
        timeout: "5s",
        retries: 6,
      },
      ...hardening,
      networks: ["internal"],
    };
    dependsOn.db = { condition: "service_healthy" };
  }
  if (plan.services.redis) {
    services.cache = {
      image: VALKEY_IMAGE,
      restart: "unless-stopped",
      command: ["valkey-server", "--appendonly", "yes"],
      volumes: ["/srv/data/valkey:/data"],
      ...hardening,
      networks: ["internal"],
    };
    dependsOn.cache = { condition: "service_started" };
  }
  if (Object.keys(dependsOn).length > 0) app.depends_on = dependsOn;

  services.caddy = {
    image: CADDY_IMAGE,
    restart: "unless-stopped",
    // In tunnel mode only the tunnel connector (host network) reaches Caddy, on a loopback port.
    ports: tunnelMode(plan)
      ? [`127.0.0.1:${TUNNEL_ORIGIN_PORT}:80`]
      : ["80:80", "443:443", "443:443/udp"],
    volumes: ["./Caddyfile:/etc/caddy/Caddyfile:ro", "caddy_data:/data", "caddy_config:/config"],
    depends_on: ["app"],
    ...hardening,
    networks: ["internal"],
  };

  const document = {
    name: plan.app.name,
    services,
    networks: { internal: {} },
    volumes: { caddy_data: {}, caddy_config: {} },
  };
  const header =
    release === undefined
      ? HEADER
      : `${HEADER}\n# \`release\` runs app.releaseCommand from opscrew/plan.yaml before each new version starts.`;
  return {
    path: "opscrew/runtime/compose.yaml",
    content: `${header}\n${stringify(document, { lineWidth: 0 })}`,
    kind: "runtime",
  };
}

/**
 * `opscrew/runtime/Caddyfile`: TLS (with a domain), compression, security headers, proxy to the app.
 * In tunnel mode Cloudflare terminates TLS and the tunnel connector reaches Caddy over plain HTTP,
 * so the sites are `http://` (no certificates, no redirect) and still send HSTS.
 */
export function renderCaddyfile(plan: DeployPlan, ctx: RenderContext): RenderedFile {
  const hosts = siteHosts(plan);
  const tunnel = tunnelMode(plan);
  const lines = [
    "# Generated by OpsCrew from opscrew/plan.yaml; `opscrew provision` regenerates it.",
  ];
  if (tunnel) {
    lines.push(
      "# Served through a Cloudflare Tunnel: Cloudflare terminates TLS, Caddy serves plain HTTP.",
    );
  } else if (ctx.acmeEmail && hosts.length > 0) {
    lines.push("{", `\temail ${ctx.acmeEmail}`, "}", "");
  }
  const sites = tunnel ? hosts.map((host) => `http://${host}`) : hosts;
  lines.push(
    `${sites.length > 0 ? sites.join(", ") : ":80"} {`,
    "\tencode zstd gzip",
    `\treverse_proxy app:${plan.app.port}`,
    "\theader {",
  );
  if (hosts.length > 0)
    lines.push('\t\tStrict-Transport-Security "max-age=31536000; includeSubDomains"');
  lines.push(
    '\t\tX-Content-Type-Options "nosniff"',
    '\t\tX-Frame-Options "SAMEORIGIN"',
    '\t\tReferrer-Policy "strict-origin-when-cross-origin"',
    "\t\t-Server",
    "\t}",
    "}",
    "",
  );
  return { path: "opscrew/runtime/Caddyfile", content: lines.join("\n"), kind: "runtime" };
}
